This version uses recursion only to find the node at position `k`. Once that node is found, its two neighboring links are changed. The recursive search also handles an out-of-range position by returning `null` without changing the list.

```java
/*
// Definition for a Node.
class ListNode {
    public int data;
    public ListNode prev;
    public ListNode next;
    public ListNode();
    public ListNode(int data);
    public ListNode(int data, ListNode prev, ListNode next);
};
*/

class Solution {
    public ListNode deleteKthElement(ListNode head, int k) {
        if (head == null || k <= 0) {
            return head;
        }

        ListNode target = findNode(head, k);
        if (target == null) {
            return head;
        }

        if (target.prev != null) {
            target.prev.next = target.next;
        } else {
            head = target.next;
        }

        if (target.next != null) {
            target.next.prev = target.prev;
        }

        target.prev = null;
        target.next = null;
        return head;
    }

    private ListNode findNode(ListNode node, int remaining) {
        if (node == null) {
            return null;
        }
        if (remaining == 1) {
            return node;
        }
        return findNode(node.next, remaining - 1);
    }
}
```

Dry run: for `4 <-> 7 <-> 9` and `k = 1`, `findNode` returns `4`. Since it has no previous node, `head` becomes `7`, and `7.prev` is set to `null`.

An empty list, zero or negative `k`, and a position beyond the list length all return the original head.

Time complexity: `O(n)`.
Space complexity: `O(n)` in the worst case because of the recursion stack.

The length is counted first, then the code chooses the closer end. This does not change the final result, but it can reduce pointer moves when `k` is near the tail. The node itself is removed by fixing its previous and next neighbors.

```cpp
/**
class ListNode
{
 * Definition for doubly-linked list.
 *  public:
 *      int data;
 *      ListNode *prev;
 *      ListNode *next;
 *      ListNode() : data(0), prev(nullptr), next(nullptr) {}
 *      ListNode(int x) : data(x), prev(nullptr), next(nullptr) {}
 *      ListNode(int x, ListNode *prev, ListNode *next) : data(x), prev(prev), next(next) {}
};
*/

class Solution {
public:
    ListNode *deleteKthElement(ListNode *&head, int k) {
        if (head == nullptr || k <= 0) {
            return head;
        }

        int length = 0;
        ListNode* tail = head;
        while (tail != nullptr) {
            ++length;
            if (tail->next == nullptr) {
                break;
            }
            tail = tail->next;
        }

        if (k > length) {
            return head;
        }

        ListNode* target = nullptr;
        if (k <= length - k + 1) {
            target = head;
            for (int position = 1; position < k; ++position) {
                target = target->next;
            }
        } else {
            target = tail;
            int stepsBack = length - k;
            for (int step = 0; step < stepsBack; ++step) {
                target = target->prev;
            }
        }

        if (target->prev != nullptr) {
            target->prev->next = target->next;
        } else {
            head = target->next;
        }

        if (target->next != nullptr) {
            target->next->prev = target->prev;
        }

        target->prev = nullptr;
        target->next = nullptr;
        return head;
    }
};
```

The first node and the last node are both covered by the same neighbor updates. The input list is changed in place.

Time complexity: `O(n)` for the length pass, with at most another `O(n)` pointer walk.
Space complexity: `O(1)`.

A temporary sentinel makes deleting the head look like deleting any other node. The code first moves to the kth node, then reconnects its neighbors. The sentinel is never returned, and the real head gets a `nil` previous pointer before returning.

```go
/** Definition for a Node.
type ListNode struct {
    Data int
    Next *ListNode
    Prev *ListNode
}
*/

func deleteKthElement(head *ListNode, k int) *ListNode {
    if head == nil || k <= 0 {
        return head
    }

    dummy := &ListNode{Next: head}
    head.Prev = dummy

    current := head
    position := 1
    for current != nil && position < k {
        current = current.Next
        position++
    }

    if current == nil {
        head.Prev = nil
        return head
    }

    previous := current.Prev
    nextNode := current.Next
    previous.Next = nextNode

    if nextNode != nil {
        nextNode.Prev = previous
    }

    head = dummy.Next
    if head != nil {
        head.Prev = nil
    }

    current.Prev = nil
    current.Next = nil
    return head
}
```

The temporary link from the original head to `dummy` is removed before every return. That matters when `k` is larger than the number of nodes.

Time complexity: `O(n)`.
Space complexity: `O(1)`.

This one stores the nodes in order first. It makes the target lookup very direct: position `k` is at index `k - 1`. The trade-off is extra memory, but the unlinking code stays easy to check.

```csharp
using System.Collections.Generic;

/*
// Definition for a Node.
public class ListNode {
    public int data;
    public ListNode prev;
    public ListNode next;
    public ListNode();
    public ListNode(int data);
    public ListNode(int data, ListNode prev, ListNode next);
}
*/

public class Solution {
    public ListNode DeleteKthElement(ListNode head, int k) {
        if (head == null || k <= 0) {
            return head;
        }

        var nodes = new List<ListNode>();
        ListNode current = head;
        while (current != null) {
            nodes.Add(current);
            current = current.next;
        }

        if (k > nodes.Count) {
            return head;
        }

        ListNode target = nodes[k - 1];
        ListNode previous = target.prev;
        ListNode nextNode = target.next;

        if (previous != null) {
            previous.next = nextNode;
        } else {
            head = nextNode;
        }

        if (nextNode != null) {
            nextNode.prev = previous;
        }

        target.prev = null;
        target.next = null;
        return head;
    }
}
```

Dry run: with `2 <-> 5 <-> 8 <-> 11` and `k = 3`, the array contains `8` at index `2`. The code links `5` directly to `11`, then sets `11.prev` to `5`.

Deleting the only node returns `null`, while deleting the last node only changes the previous node's `next` pointer.

Time complexity: `O(n)`.
Space complexity: `O(n)` for the stored node references.

A simple forward walk is enough here. The list uses 1-based positions, so the node where the counter reaches `k` is removed. Both links around that node are updated, and a new head is returned when the first node is deleted.

```python
# Definition for a Node.
class ListNode:
    def __init__(self, data, prev=None, next=None):
        self.data = data
        self.prev = prev
        self.next = next


class Solution:
    def deleteKthElement(self, head: ListNode, k: int) -> ListNode:
        if head is None or k <= 0:
            return head

        current = head
        position = 1

        while current is not None and position < k:
            current = current.next
            position += 1

        if current is None:
            return head

        if current.prev is not None:
            current.prev.next = current.next
        else:
            head = current.next

        if current.next is not None:
            current.next.prev = current.prev

        current.prev = None
        current.next = None
        return head
```

For example, in `10 <-> 20 <-> 30`, deleting `k = 2` connects `10.next` to `30` and `30.prev` to `10`. A `k` larger than the list length leaves the list unchanged.

Time complexity: `O(n)` in the worst case.
Space complexity: `O(1)`.

