/**
class ListNode
{
 * Definition for doubly-linked list.
 *  public:
 *      int data;
 *      ListNode *prev;
 *      ListNode *next;
 *      ListNode() : data(0), prev(nullptr), next(nullptr) {}
 *      ListNode(int x) : data(x), prev(nullptr), next(nullptr) {}
 *      ListNode(int x, ListNode *prev, ListNode *next) : data(x), prev(prev), next(next) {}
};
*/

class Solution {
public:
    ListNode *deleteKthElement(ListNode *&head, int k) {

        // if k <= 0 then edge case will be : 
        if(head == nullptr || k <= 0){
            return nullptr ;
        }

        int count = 0; 
        ListNode * temp = head ;

        while(temp != nullptr){
            count ++ ;

            if(count == k){
                break ;
            }

            temp = temp -> next ;
        }

        // if k > length of the ListNode : edge case :
        if(temp == nullptr ){
            return head ;
        }

        ListNode * prev = temp -> prev ;
        ListNode * front = temp -> next ;

        // now node to be deleted 
        if(prev == nullptr && front == nullptr){
            delete temp ;
            return nullptr ;
        }
        // if node is at the head node : head of the ListNode
        else if(prev == nullptr){
           head = front ;
           head -> prev = nullptr ;
           delete temp ;
        }
        // if the node is at the tail node : delete the tail of the ListNode
        else if(front == nullptr){
            prev -> next = nullptr ;
            temp -> prev = nullptr ;
            delete temp ;
        }
        // else the temp is in the middle :
        else{

            prev -> next = temp -> next ;
            front -> prev = temp -> prev ;

            temp -> next = nullptr ;
            temp -> prev = nullptr ;
            delete temp ;

        }

        return head ;

    }
};
